function validate(input) {
  const [{ Customers = [], Orders = [] }] = input;
  const customers = new Set(), orders = new Set();
  for (const [id, name] of Customers) {
    if (id === null || name === null) return 'Customers rows may not contain null.';
    if (customers.has(id)) return `customer_id ${id} appears twice in Customers.`;
    customers.add(id);
  }
  for (const [id, customer, product] of Orders) {
    if (id === null || customer === null || product === null) return 'Orders rows may not contain null.';
    if (orders.has(id)) return `order_id ${id} appears twice in Orders.`;
    if (!customers.has(customer)) return `Order ${id} names unknown customer ${customer}.`;
    orders.add(id);
  }
  return null;
}

