function generate(rand, size) {
  const names = ['Daniel', 'Diana', 'Elizabeth', 'Jhon', 'Mia', 'Omar'];
  const small = size === 'small';
  const products = small ? ['A', 'B', 'C', 'D'] : ['A', 'B', 'C', 'D', 'E'];
  const count = small ? Math.floor(rand() * 6) : 600;
  const ids = Array.from({ length: count }, (_, i) => i + 1);
  for (let i = ids.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [ids[i], ids[j]] = [ids[j], ids[i]]; }
  const Customers = ids.map((id) => [id, names[Math.floor(rand() * names.length)]]);
  const Orders = [];
  const orderCount = count === 0 ? 0 : small ? Math.floor(rand() * 9) : 2000;
  for (let i = 0; i < orderCount; i++) {
    // Products A and B are common so that many customers have both; C is rarer.
    const r = rand();
    const product = r < 0.35 ? 'A' : r < 0.7 ? 'B' : products[2 + Math.floor(rand() * (products.length - 2))];
    Orders.push([(i + 1) * 10, ids[Math.floor(rand() * (small ? Math.min(count, 3) : count))], product]);
  }
  return [{ Customers, Orders }];
}
